create or replace function public.borrow_schoolpro_library_book(p_book uuid,p_student uuid default null,p_member uuid default null,p_due timestamptz default null) returns uuid language plpgsql security definer set search_path='' as $$declare b public.schoolpro_library_books;lid uuid;begin select * into b from public.schoolpro_library_books where id=p_book for update;if b.id is null then raise exception 'Book not found';end if;if not(public.schoolpro_member_can_manage(b.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=b.school_id and m.user_id=auth.uid() and m.role::text='librarian')) then raise exception 'Not authorized';end if;if b.available_copies<=0 then raise exception 'No available copy';end if;if (p_student is null)=(p_member is null) then raise exception 'Choose exactly one borrower';end if;insert into public.schoolpro_library_loans(school_id,book_id,student_id,member_id,due_at,status) values(b.school_id,b.id,p_student,p_member,coalesce(p_due,now()+interval '14 days'),'borrowed') returning id into lid;update public.schoolpro_library_books set available_copies=available_copies-1 where id=b.id;return lid;end$$;
create or replace function public.return_schoolpro_library_book(p_loan uuid,p_fine numeric default 0) returns void language plpgsql security definer set search_path='' as $$declare l public.schoolpro_library_loans;begin select * into l from public.schoolpro_library_loans where id=p_loan for update;if l.id is null then raise exception 'Loan not found';end if;if not(public.schoolpro_member_can_manage(l.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=l.school_id and m.user_id=auth.uid() and m.role::text='librarian')) then raise exception 'Not authorized';end if;if l.returned_at is not null then return;end if;update public.schoolpro_library_loans set returned_at=now(),fine=greatest(coalesce(p_fine,0),0),status='returned' where id=l.id;update public.schoolpro_library_books set available_copies=least(copies,available_copies+1) where id=l.book_id;end$$;
create or replace function public.apply_schoolpro_promotion(p_promotion uuid) returns void language plpgsql security definer set search_path='' as $$declare p public.schoolpro_promotions;begin select * into p from public.schoolpro_promotions where id=p_promotion for update;if p.id is null then raise exception 'Promotion not found';end if;if not(public.schoolpro_member_can_manage(p.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=p.school_id and m.user_id=auth.uid() and m.role::text in('registrar','head_teacher','vice_principal'))) then raise exception 'Not authorized';end if;if p.status='applied' then return;end if;update public.schoolpro_students set class_name=p.to_class where id=p.student_id and school_id=p.school_id;update public.schoolpro_promotions set status='applied' where id=p.id;end$$;
revoke all on function public.borrow_schoolpro_library_book(uuid,uuid,uuid,timestamptz) from public;grant execute on function public.borrow_schoolpro_library_book(uuid,uuid,uuid,timestamptz) to authenticated;revoke all on function public.return_schoolpro_library_book(uuid,numeric) from public;grant execute on function public.return_schoolpro_library_book(uuid,numeric) to authenticated;revoke all on function public.apply_schoolpro_promotion(uuid) from public;grant execute on function public.apply_schoolpro_promotion(uuid) to authenticated;